insert into public.ai_generations (id, user_id, situation, prompt, caption, style, model, image_path, created_at)
values
  ('b2f16ba9-e767-448d-aa0d-279e4bd78f8e', '5725f5d0-f491-4737-83c1-049679099e39', 'Waiting for the professor to release midterm grades.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"midterms","template":{"name":"Waiting Skeleton","url":"https://i.imgflip.com/2fm6x.jpg","width":298,"height":403,"page":"https://imgflip.com/memetemplate/4087833"},"source":"https://imgflip.com/api"}', 'Midterm grades are coming soon. A very flexible definition of soon.', 'dry', 'mock-internet-memes-v1', 'https://i.imgflip.com/2fm6x.jpg', now() - interval '0 hours'),
  ('64422b6b-4d25-4c6a-a8c7-0086651cc31e', '5725f5d0-f491-4737-83c1-049679099e39', 'Every empty seat in Butler Library has a backpack on it.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"butler","template":{"name":"Ancient Aliens","url":"https://i.imgflip.com/26am.jpg","width":500,"height":437,"page":"https://imgflip.com/memetemplate/101470"},"source":"https://imgflip.com/api"}', 'The only explanation for every Butler seat being saved: interdimensional students.', 'absurd', 'mock-internet-memes-v1', 'https://i.imgflip.com/26am.jpg', now() - interval '8 hours'),
  ('dceece69-4cde-4a25-ab0e-1e21787a2c47', '5725f5d0-f491-4737-83c1-049679099e39', 'A roommate brings enough snacks for everyone in the dorm.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"dorm-life","template":{"name":"Oprah You Get A","url":"https://i.imgflip.com/gtj5t.jpg","width":620,"height":465,"page":"https://imgflip.com/memetemplate/28251713"},"source":"https://imgflip.com/api"}', 'My roommate bought extra snacks and suddenly the dorm felt like home.', 'wholesome', 'mock-internet-memes-v1', 'https://i.imgflip.com/gtj5t.jpg', now() - interval '16 hours'),
  ('367b9535-a04b-4e77-ac0a-73dbad329953', '5725f5d0-f491-4737-83c1-049679099e39', 'Trying to identify today''s special in the dining hall.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"dining-hall","template":{"name":"Woman Yelling At Cat","url":"https://i.imgflip.com/345v97.jpg","width":680,"height":438,"page":"https://imgflip.com/memetemplate/188390779"},"source":"https://imgflip.com/api"}', 'The dining hall called it a seasonal bowl. The season is confusion.', 'dry', 'mock-internet-memes-v1', 'https://i.imgflip.com/345v97.jpg', now() - interval '24 hours'),
  ('7d6eee39-1191-4cef-af98-2bc4f1b0e5b7', '5725f5d0-f491-4737-83c1-049679099e39', 'The subway has been one minute away for twenty minutes.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"subway","template":{"name":"Always Has Been","url":"https://i.imgflip.com/46e43q.png","width":960,"height":540,"page":"https://imgflip.com/memetemplate/252600902"},"source":"https://imgflip.com/api"}', 'Wait, the MTA countdown is measured in dog years? Always has been.', 'absurd', 'mock-internet-memes-v1', 'https://i.imgflip.com/46e43q.png', now() - interval '32 hours'),
  ('818659ea-d089-4b5f-af1b-f2920f7cfb64', '5725f5d0-f491-4737-83c1-049679099e39', 'A friend remembers your coffee order before an early class.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"coffee","template":{"name":"Leonardo Dicaprio Cheers","url":"https://i.imgflip.com/39t1o.jpg","width":600,"height":400,"page":"https://imgflip.com/memetemplate/5496396"},"source":"https://imgflip.com/api"}', 'To the friend who knows my coffee order: you are the most reliable part of my morning.', 'wholesome', 'mock-internet-memes-v1', 'https://i.imgflip.com/39t1o.jpg', now() - interval '40 hours'),
  ('c69cfc57-27bc-4aa4-a0af-81302643df76', '5725f5d0-f491-4737-83c1-049679099e39', 'The study group discovers a much more interesting conversation than the problem set.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"study-groups","template":{"name":"Distracted Boyfriend","url":"https://i.imgflip.com/1ur9b0.jpg","width":1200,"height":800,"page":"https://imgflip.com/memetemplate/112126428"},"source":"https://imgflip.com/api"}', 'Our study group has covered everything except the material.', 'dry', 'mock-internet-memes-v1', 'https://i.imgflip.com/1ur9b0.jpg', now() - interval '48 hours'),
  ('5b88726a-3b81-4417-a00b-fb2eefdd1d6b', '5725f5d0-f491-4737-83c1-049679099e39', 'The professor says the final exam is cumulative, including knowledge from before birth.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"professors","template":{"name":"Expanding Brain","url":"https://i.imgflip.com/1jwhww.jpg","width":857,"height":1202,"page":"https://imgflip.com/memetemplate/93895088"},"source":"https://imgflip.com/api"}', 'Lecture notes. Textbook. Entire internet. The professor''s childhood memories. All on the exam.', 'absurd', 'mock-internet-memes-v1', 'https://i.imgflip.com/1jwhww.jpg', now() - interval '56 hours'),
  ('244c3143-0af4-4995-a0b1-e20b81973730', '5725f5d0-f491-4737-83c1-049679099e39', 'A friend shares their exam notes and helps you prepare for midterms.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"midterms","template":{"name":"Epic Handshake","url":"https://i.imgflip.com/28j0te.jpg","width":900,"height":645,"page":"https://imgflip.com/memetemplate/135256802"},"source":"https://imgflip.com/api"}', 'You brought the notes. I brought the snacks. We brought each other through midterms.', 'wholesome', 'mock-internet-memes-v1', 'https://i.imgflip.com/28j0te.jpg', now() - interval '64 hours'),
  ('2bd3c2b8-423c-4718-aabe-dca03cdee903', '5725f5d0-f491-4737-83c1-049679099e39', 'Searching Butler Library for a quiet seat next to an available outlet.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"butler","template":{"name":"One Does Not Simply","url":"https://i.imgflip.com/1bij.jpg","width":568,"height":335,"page":"https://imgflip.com/memetemplate/61579"},"source":"https://imgflip.com/api"}', 'One does not simply find an outlet in Butler.', 'dry', 'mock-internet-memes-v1', 'https://i.imgflip.com/1bij.jpg', now() - interval '72 hours'),
  ('2ae070f5-2a53-497e-a25f-346e39b5f4d2', '5725f5d0-f491-4737-83c1-049679099e39', 'A roommate''s plan to make a tiny dorm room feel bigger gets out of hand.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"dorm-life","template":{"name":"Gru''s Plan","url":"https://i.imgflip.com/26jxvz.jpg","width":700,"height":449,"page":"https://imgflip.com/memetemplate/131940431"},"source":"https://imgflip.com/api"}', 'Step 1: rearrange the dorm. Step 2: remove the furniture. Step 3: become the furniture.', 'absurd', 'mock-internet-memes-v1', 'https://i.imgflip.com/26jxvz.jpg', now() - interval '80 hours'),
  ('323551b2-4446-4f65-a542-f777391ae6bc', '5725f5d0-f491-4737-83c1-049679099e39', 'A friend saves the last cookie at John Jay dining hall.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"dining-hall","template":{"name":"Epic Handshake","url":"https://i.imgflip.com/28j0te.jpg","width":900,"height":645,"page":"https://imgflip.com/memetemplate/135256802"},"source":"https://imgflip.com/api"}', 'A friend saved me the last cookie at John Jay. Small cookie. Enormous act of friendship.', 'wholesome', 'mock-internet-memes-v1', 'https://i.imgflip.com/28j0te.jpg', now() - interval '88 hours'),
  ('b24c5ae6-ccce-4dcf-a0f6-d9eee809ca37', '5725f5d0-f491-4737-83c1-049679099e39', 'Waiting for the next subway train while the arrival estimate keeps changing.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"subway","template":{"name":"Waiting Skeleton","url":"https://i.imgflip.com/2fm6x.jpg","width":298,"height":403,"page":"https://imgflip.com/memetemplate/4087833"},"source":"https://imgflip.com/api"}', 'The MTA says the train is arriving. I admire its optimism.', 'dry', 'mock-internet-memes-v1', 'https://i.imgflip.com/2fm6x.jpg', now() - interval '96 hours'),
  ('c984bad8-c70f-44ca-aaf5-c4cbc56cf1f1', '5725f5d0-f491-4737-83c1-049679099e39', 'Having another coffee after already drinking four espressos.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"coffee","template":{"name":"This Is Fine","url":"https://i.imgflip.com/wxica.jpg","width":580,"height":282,"page":"https://imgflip.com/memetemplate/55311130"},"source":"https://imgflip.com/api"}', 'Five coffees in. I can hear the Wi-Fi, but the deadline still can''t hear me.', 'absurd', 'mock-internet-memes-v1', 'https://i.imgflip.com/wxica.jpg', now() - interval '104 hours'),
  ('4b3d27c2-0ff1-4613-a423-b85f2264d79c', '5725f5d0-f491-4737-83c1-049679099e39', 'A study buddy patiently explains the same problem for the fourth time.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"study-groups","template":{"name":"Epic Handshake","url":"https://i.imgflip.com/28j0te.jpg","width":900,"height":645,"page":"https://imgflip.com/memetemplate/135256802"},"source":"https://imgflip.com/api"}', 'A good study buddy explains it again without making you feel bad for asking.', 'wholesome', 'mock-internet-memes-v1', 'https://i.imgflip.com/28j0te.jpg', now() - interval '112 hours'),
  ('36a69f93-fbce-485d-ad0e-1a10d88c0381', '5725f5d0-f491-4737-83c1-049679099e39', 'The professor says the lecture slides will be posted after class.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"professors","template":{"name":"Drake Hotline Bling","url":"https://i.imgflip.com/30b1gx.jpg","width":1200,"height":1200,"page":"https://imgflip.com/memetemplate/181913649"},"source":"https://imgflip.com/api"}', 'Taking notes during lecture? No. Refreshing the course page until the slides appear? Absolutely.', 'dry', 'mock-internet-memes-v1', 'https://i.imgflip.com/30b1gx.jpg', now() - interval '120 hours'),
  ('6efd0694-96e9-4ac9-a624-a267444e4754', '5725f5d0-f491-4737-83c1-049679099e39', 'Finishing an exam after studying every chapter except the one on the test.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"midterms","template":{"name":"Disaster Girl","url":"https://i.imgflip.com/23ls.jpg","width":500,"height":375,"page":"https://imgflip.com/memetemplate/97984"},"source":"https://imgflip.com/api"}', 'I studied every chapter except the one on the midterm. An impressively precise miss.', 'absurd', 'mock-internet-memes-v1', 'https://i.imgflip.com/23ls.jpg', now() - interval '128 hours'),
  ('5036ebff-c4e9-47b7-a0cb-d2fd50a42103', '5725f5d0-f491-4737-83c1-049679099e39', 'Someone leaves an encouraging note on your desk in Butler Library.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"butler","template":{"name":"Leonardo Dicaprio Cheers","url":"https://i.imgflip.com/39t1o.jpg","width":600,"height":400,"page":"https://imgflip.com/memetemplate/5496396"},"source":"https://imgflip.com/api"}', 'A stranger left a ''you''ve got this'' note in Butler. For a moment, I believed both of us.', 'wholesome', 'mock-internet-memes-v1', 'https://i.imgflip.com/39t1o.jpg', now() - interval '136 hours'),
  ('134236aa-cb55-4ce9-a217-0479a68a88e4', '5725f5d0-f491-4737-83c1-049679099e39', 'Choosing between sleep and a late-night microwave snack while your roommate is asleep.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"dorm-life","template":{"name":"Two Buttons","url":"https://i.imgflip.com/1g8my4.jpg","width":600,"height":908,"page":"https://imgflip.com/memetemplate/87743020"},"source":"https://imgflip.com/api"}', 'Roommate asleep. Microwave beeping. Diplomacy has entered its hardest hour.', 'dry', 'mock-internet-memes-v1', 'https://i.imgflip.com/1g8my4.jpg', now() - interval '144 hours'),
  ('c78540b4-826f-4b67-a462-b2a3ecc4e65a', '5725f5d0-f491-4737-83c1-049679099e39', 'The Ferris dining hall pasta seems to have a personality of its own.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"dining-hall","template":{"name":"Ancient Aliens","url":"https://i.imgflip.com/26am.jpg","width":500,"height":437,"page":"https://imgflip.com/memetemplate/101470"},"source":"https://imgflip.com/api"}', 'Ferris pasta achieved sentience and immediately asked to change its meal plan.', 'absurd', 'mock-internet-memes-v1', 'https://i.imgflip.com/26am.jpg', now() - interval '152 hours'),
  ('24ef0f58-2711-4aac-a87a-c4e67b50bd6f', '5725f5d0-f491-4737-83c1-049679099e39', 'A stranger helps carry a heavy bag up the subway stairs.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"subway","template":{"name":"Leonardo Dicaprio Cheers","url":"https://i.imgflip.com/39t1o.jpg","width":600,"height":400,"page":"https://imgflip.com/memetemplate/5496396"},"source":"https://imgflip.com/api"}', 'Someone carried my bag up the subway stairs. New York still has a soft side.', 'wholesome', 'mock-internet-memes-v1', 'https://i.imgflip.com/39t1o.jpg', now() - interval '160 hours'),
  ('34d3f3f0-7b59-4112-afca-8afb267fc468', '5725f5d0-f491-4737-83c1-049679099e39', 'Buying a latte instead of addressing an ever-growing to-do list.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"coffee","template":{"name":"Roll Safe Think About It","url":"https://i.imgflip.com/1h7in3.jpg","width":702,"height":395,"page":"https://imgflip.com/memetemplate/89370399"},"source":"https://imgflip.com/api"}', 'If I hold a coffee, it counts as getting a handle on things.', 'dry', 'mock-internet-memes-v1', 'https://i.imgflip.com/1h7in3.jpg', now() - interval '168 hours'),
  ('c77a3d9a-311d-4c45-ab0e-a26b14a1e730', '5725f5d0-f491-4737-83c1-049679099e39', 'A study group spends two hours planning the next study group meeting.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"study-groups","template":{"name":"Expanding Brain","url":"https://i.imgflip.com/1jwhww.jpg","width":857,"height":1202,"page":"https://imgflip.com/memetemplate/93895088"},"source":"https://imgflip.com/api"}', 'Our study group formed a committee to schedule the meeting about starting the homework.', 'absurd', 'mock-internet-memes-v1', 'https://i.imgflip.com/1jwhww.jpg', now() - interval '176 hours'),
  ('7d36dc7c-cdd8-4b1a-acdb-48e11887d1e6', '5725f5d0-f491-4737-83c1-049679099e39', 'A professor stays after office hours to help a student understand a difficult concept.', '{"kind":"mock","batch":"mock-internet-memes-v1","topic":"professors","template":{"name":"Leonardo Dicaprio Cheers","url":"https://i.imgflip.com/39t1o.jpg","width":600,"height":400,"page":"https://imgflip.com/memetemplate/5496396"},"source":"https://imgflip.com/api"}', 'The professor stayed until it clicked. Sometimes the best part of college is someone making time.', 'wholesome', 'mock-internet-memes-v1', 'https://i.imgflip.com/39t1o.jpg', now() - interval '184 hours')
